 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    for r, c in points:
        # Upper cap and inner stem.
        for cc in range(max(0, c - 2), min(w, c + 3)):
            if 0 <= r - 2 < h:
                out[r - 2][cc] = 5
        if 0 <= r - 1 < h and 0 <= c < w:
            out[r - 1][c] = 5
        # Side rails around the marker.
        for rr in range(r - 1, r + 2):
            if 0 <= rr < h:
                for cc in (c - 2, c + 2):
                    if 0 <= cc < w:
                        out[rr][cc] = 2
        # Full-width lower beam, with the five-cell center colored 8.
        if 0 <= r + 2 < h:
            out[r + 2] = [2] * w
            for cc in range(max(0, c - 2), min(w, c + 3)):
                out[r + 2][cc] = 8
        out[r][c] = 3
    return out
